// NOTE: Rotating text animation component from React Bits
'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence, Transition, Variant } from 'motion/react';
import { cn } from '@/lib/utils';

interface RotatingTextProps {
  /** Array of texts to rotate through */
  texts: string[];
  /** ClassName applied to the main container */
  mainClassName?: string;
  /** Direction to stagger the letter animations from */
  staggerFrom?: 'first' | 'last' | 'center';
  /** Initial animation state for each letter */
  initial?: Variant;
  /** Animate state for each letter */
  animate?: Variant;
  /** Exit animation state for each letter */
  exit?: Variant;
  /** Duration between each letter animation in stagger */
  staggerDuration?: number;
  /** ClassName applied to each letter wrapper */
  splitLevelClassName?: string;
  /** Transition configuration for letter animations */
  transition?: Transition;
  /** Interval in ms between text rotations */
  rotationInterval?: number;
}

export default function RotatingText({
  texts,
  mainClassName = '',
  staggerFrom = 'first',
  initial = { y: '100%' },
  animate = { y: 0 },
  exit = { y: '-120%' },
  staggerDuration = 0.025,
  splitLevelClassName = '',
  transition = { type: 'spring', damping: 30, stiffness: 400 },
  rotationInterval = 2000,
}: Readonly<RotatingTextProps>) {
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prevIndex) => (prevIndex + 1) % texts.length);
    }, rotationInterval);

    return () => clearInterval(interval);
  }, [texts.length, rotationInterval]);

  const currentText = texts[currentIndex];
  const letters = currentText.split('');

  // NOTE: Calculate stagger delay based on direction
  const getStaggerDelay = (index: number) => {
    const length = letters.length;
    switch (staggerFrom) {
      case 'last':
        return (length - 1 - index) * staggerDuration;
      case 'center':
        return Math.abs(Math.floor(length / 2) - index) * staggerDuration;
      case 'first':
      default:
        return index * staggerDuration;
    }
  };

  return (
    <div className={cn('inline-flex', mainClassName)}>
      <AnimatePresence mode="wait">
        <motion.div
          key={currentIndex}
          className="flex"
          initial="hidden"
          animate="visible"
          exit="exit"
        >
          {letters.map((letter, index) => (
            <motion.span
              key={`${currentIndex}-${index}`}
              className={cn('inline-block', splitLevelClassName)}
              custom={index}
              variants={{
                hidden: initial,
                visible: animate,
                exit: exit,
              }}
              transition={{
                ...transition,
                delay: getStaggerDelay(index),
              }}
            >
              {letter === ' ' ? '\u00A0' : letter}
            </motion.span>
          ))}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}
